function rotate(entries, position) {
  const ordered = [...entries];
  const [correct] = ordered.splice(0, 1);
  ordered.splice(position, 0, correct);
  return ordered;
}

function difficultyFor(questionIndex) {
  if (questionIndex < 4) return 3;
  if (questionIndex < 13) return 4;
  return 5;
}

function buildProfileCases([source, domainKey, profileKey, sourceSection], profileIndex) {
  const domain = DOMAIN_LIBRARY[domainKey];
  const questions = [];
  const ageSeed = 29 + profileIndex;

  for (let series = 0; series < 4; series += 1) {
    const age = ageSeed + (series * 7);
    const seriesId = `${profileKey}-serie-${series + 1}`;
    const patientContext = `${domain.base(age)} ${domain.variants[series]}`;

    domain.facts.forEach((fact, factIndex) => {
      const questionIndex = (series * domain.facts.length) + factIndex;
      const entries = [
        option(fact.answer, `Es la mejor elección. ${fact.rationale}`),
        ...fact.wrong,
      ];
      const shuffled = rotate(entries, (profileIndex + questionIndex) % 5);
      const answer = shuffled.findIndex((entry) => entry.text === fact.answer);

      questions.push({
        id: 30001 + (profileIndex * 20) + questionIndex,
        caseSet: seriesId,
        caseSeriesId: seriesId,
        step: factIndex + 1,
        specialty: domain.specialty,
        subtopic: sourceSection,
        difficulty: difficultyFor(questionIndex),
        source,
        sourceConcept: fact.concept,
        sourceMode: "generated-from-word-summary",
        generated: true,
        tags: [domainKey, fact.concept, profileKey],
        title: `Caso ${String(30001 + (profileIndex * 20) + questionIndex).padStart(5, "0")}`,
        case: patientContext,
        question: `En esta valoración independiente de una persona de ${age} años, ${fact.prompt}`,
        options: shuffled.map((entry) => entry.text),
        answer,
        explanation: `${fact.rationale}\n\nPunto clave: ${fact.answer}.`,
        optionFeedback: shuffled.map((entry, index) => index === answer
          ? `Correcta. ${entry.reason}`
          : `No es la mejor elección en este caso. ${entry.reason}`),
      });
    });
  }
  return questions;
}

const massiveWordExpansionCases = profiles.flatMap(buildProfileCases);

export const massiveWordExpansionManifest = profiles.map(([source, domainKey, profileKey, sourceSection], index) => ({
  source,
  domain: domainKey,
  profileKey,
  sourceSection,
  questions: 20,
  firstId: 30001 + (index * 20),
  lastId: 30020 + (index * 20),
}));

export default massiveWordExpansionCases;
